package school.magiccodex.discovery;
import org.junit.jupiter.api.Test;import org.bukkit.configuration.file.YamlConfiguration;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class CurrentReviewedMappingTest {
 // Arcana learning conditions are explicitly upstream-pending; do not invent rules or extend legacy meteor prerequisites.
 static final Set<String> ARCANA_PENDING=Set.of("shadow_double","echo_reading","sealing_thread","shadow_exchange","forbidden_contract","life_siphon","misfortune_whisper","hungry_shadow","curse_transfer","discord","night_chain","pain_deferral","black_harvest","ink_fingertip","shadow_nail","night_lullaby","loosen_grasp","healing_seal","shadow_scales","warning_thread","wound_accounting","inverted_offering","ghost_tool","bell_of_fear","eclipse_eye","void_maw","landing_airbrake","hushed_soles","thorn_manners","cinder_skipring","droplet_relay","folding_tideplane");
 @Test void meteorPreservesAllOtherLegacyFirePrerequisitesWithoutAddingKillOnlyMobSpells()throws Exception{var fire=new HashSet<String>();try(var files=Files.list(Path.of("../magic-codex-fabric/src/main/resources/assets/magiccodex/default-spells"))){for(var path:files.filter(p->p.toString().endsWith(".yml")).toList()){var yaml=YamlConfiguration.loadConfiguration(path.toFile());if(yaml.getInt("order")<300 && "fire".equals(yaml.getString("category")) && !"cinder_skipring".equals(yaml.getString("id")))fire.add("magic.learned."+yaml.getString("id"));}}assertEquals(49,fire.size());fire.remove("magic.learned.falling_star");var definitions=new Definitions(Path.of("src/main/resources/discoveries.yml").toFile());assertEquals(fire,new HashSet<>(definitions.spells.get("falling_star").prerequisites()));}
 @Test void currentAndExpansionMappingsAndRemainingGapsAreExact()throws Exception{var catalog=YamlConfiguration.loadConfiguration(Path.of("../portable-vfx-runtime/paper/src/main/resources/spell-catalog.yml").toFile()).getConfigurationSection("spells");var definitions=new Definitions(Path.of("src/main/resources/discoveries.yml").toFile());definitions.manual(Path.of("src/main/resources/manual-conditions.yml").toFile());var missing=new HashSet<String>();int reviewed=0,manual=0,expansion=0;for(var id:catalog.getKeys(false))if(catalog.getBoolean(id+".reviewed")){boolean added=catalog.getInt(id+".number")>=101 && catalog.getInt(id+".number")<=167 && catalog.getInt(id+".number")!=149;if(added)expansion++;else reviewed++;if(definitions.manual.containsKey(id)){if(!added)manual++;}else if(!definitions.spells.containsKey(id)||Definitions.PENDING.contains(id))missing.add(id);}assertEquals(59,expansion);assertEquals(122+ARCANA_PENDING.size(),reviewed);assertEquals(78,manual);var expected=new HashSet<>(Set.of("crimson_heart","bouncing_droplet","constellation_blessing","material_exchange","dormant_seed","mana_deposit","flint_sorting","compost_return","moss_coating"));expected.addAll(ARCANA_PENDING);assertEquals(expected,missing);}
}
